import pytest

from bedrock_protocol import nbt, v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.BlockActorData{Position: protocol.BlockPos{-1, 320, 3}, NBTData: map[string]any{"id": "Chest"}}
CHEST = bytes.fromhex("018005060a000802696405436865737400")

# generated by gophertunnel b8bd735:
# packet.BlockActorData{Position: protocol.BlockPos{1, 2, 3}}
EMPTY_TAG = bytes.fromhex("0204060a0000")

# generated by gophertunnel b8bd735:
# packet.BlockActorData{Position: protocol.BlockPos{-1, -1, -1}}
NEGATIVE_POSITION = bytes.fromhex("0101010a0000")

# generated by gophertunnel b8bd735:
# packet.BlockActorData{NBTData: map[string]any{"a": []map[string]any{}}}
EMPTY_COMPOUND_LIST = bytes.fromhex("0000000a000901610a0000")

# generated by gophertunnel b8bd735:
# packet.BlockActorData{NBTData: map[string]any{"o": []any{[]string{}, []int64{}}}}
NESTED_EMPTY_LISTS = bytes.fromhex("0000000a0009016f09040800040000")

GOLDENS = [
    pytest.param(
        v2225.BlockActorDataPacket(
            pos=v2225.BlockPos(x=-1, y=320, z=3),
            data=nbt.CompoundTag({"id": nbt.StringTag("Chest")}),
        ),
        CHEST,
        id="chest",
    ),
    pytest.param(v2225.BlockActorDataPacket(pos=v2225.BlockPos(x=1, y=2, z=3)), EMPTY_TAG, id="empty-tag"),
    pytest.param(
        v2225.BlockActorDataPacket(pos=v2225.BlockPos(x=-1, y=-1, z=-1)),
        NEGATIVE_POSITION,
        id="negative-position",
    ),
    pytest.param(
        v2225.BlockActorDataPacket(data=nbt.CompoundTag({"a": nbt.ListTag(type=10)})),
        EMPTY_COMPOUND_LIST,
        id="empty-list-keeps-its-element-type",
    ),
    pytest.param(
        v2225.BlockActorDataPacket(
            data=nbt.CompoundTag({"o": nbt.ListTag([nbt.ListTag(type=8), nbt.ListTag(type=4)])}),
        ),
        NESTED_EMPTY_LISTS,
        id="nested-empty-lists-keep-their-element-types",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_block_actor_data_is_packet_56(version):
    assert version.packets[56] is version.BlockActorDataPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_block_actor_data_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_block_actor_data_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.xfail(strict=True, reason="binding gap: ListTag has no clear()")
def test_clearing_a_list_resets_its_type():
    tags = nbt.ListTag([nbt.IntTag(1)])
    tags.clear()
    assert tags.type == 0


@pytest.mark.parametrize(
    "cls",
    [
        nbt.ByteTag,
        nbt.ShortTag,
        nbt.IntTag,
        nbt.Int64Tag,
        nbt.FloatTag,
        nbt.DoubleTag,
        nbt.StringTag,
        nbt.ByteArrayTag,
        nbt.IntArrayTag,
        nbt.ListTag,
        nbt.CompoundTag,
    ],
    ids=lambda cls: cls.__name__,
)
def test_every_tag_class_is_a_tag(cls):
    assert isinstance(cls(), nbt.Tag)


@pytest.mark.parametrize(
    ("function", "shown"),
    [
        pytest.param(nbt.ListTag.append, "arg: bedrock_protocol.nbt.Tag, /", id="argument"),
        pytest.param(nbt.CompoundTag.__getitem__, "-> bedrock_protocol.nbt.Tag | None", id="return"),
    ],
)
def test_a_signature_names_a_tag_as_nbt_tag(function, shown):
    assert shown in function.__doc__


def test_a_compound_key_view_sees_a_key_added_after_it():
    tag = nbt.CompoundTag()
    keys = tag.keys()
    tag["id"] = nbt.StringTag("Chest")
    assert list(keys) == ["id"]


def test_a_compound_raises_key_error_for_a_missing_key():
    with pytest.raises(KeyError, match=r"^''$"):
        nbt.CompoundTag()["id"]


def test_a_compound_is_unhashable():
    with pytest.raises(TypeError, match="unhashable"):
        hash(nbt.CompoundTag())


def test_a_list_built_in_code_takes_its_type_from_the_first_element():
    tags = nbt.ListTag()
    assert tags.type == 0
    tags.append(nbt.IntTag(1))
    assert tags.type == 3


def test_a_list_rejects_an_element_of_another_type():
    tags = nbt.ListTag([nbt.IntTag(1)])
    with pytest.raises(ValueError, match="share one type"):
        tags.append(nbt.StringTag("x"))


def test_a_typed_empty_list_rejects_an_element_of_another_type():
    with pytest.raises(ValueError, match="share one type"):
        nbt.ListTag(type=10).append(nbt.IntTag(1))


def test_a_typed_empty_list_differs_from_an_untyped_one():
    assert nbt.ListTag(type=10) != nbt.ListTag()


@pytest.mark.parametrize("type", [12, -1], ids=["above", "below"])
def test_a_list_rejects_a_type_that_is_not_a_tag_type(type):
    with pytest.raises(ValueError, match=rf"^type: {type} is not a tag type$"):
        nbt.ListTag(type=type)


def test_a_list_type_is_an_nbt_type_equal_to_its_int():
    tags = nbt.ListTag([nbt.IntTag(1)])
    assert isinstance(tags.type, nbt.Type)
    assert tags.type == 3


@pytest.mark.parametrize("type", [nbt.Type.COMPOUND, 10], ids=["enum", "int"])
def test_a_list_takes_its_type_as_an_nbt_type_or_an_int(type):
    assert nbt.ListTag(type=type).type is nbt.Type.COMPOUND


def test_an_empty_list_defaults_to_the_end_type():
    assert nbt.ListTag().type is nbt.Type.END


@pytest.mark.parametrize(
    ("name", "value"),
    [
        ("END", 0),
        ("BYTE", 1),
        ("SHORT", 2),
        ("INT", 3),
        ("INT64", 4),
        ("FLOAT", 5),
        ("DOUBLE", 6),
        ("BYTE_ARRAY", 7),
        ("STRING", 8),
        ("LIST", 9),
        ("COMPOUND", 10),
        ("INT_ARRAY", 11),
    ],
)
def test_an_nbt_type_value_has_its_member_name(name, value):
    assert nbt.Type(value).name == name


def test_nbt_type_has_only_the_twelve_members():
    assert len(nbt.Type) == 12


@pytest.mark.parametrize("cls", [nbt.IntTag, nbt.StringTag, nbt.IntArrayTag, nbt.ListTag, nbt.CompoundTag])
def test_a_tag_class_cannot_be_subclassed(cls):
    with pytest.raises(TypeError, match="prohibits subclassing"):
        type("Sub", (cls,), {})
